// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health/live", wrapper.GetLiveness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health/ready", wrapper.GetReadiness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/me", wrapper.GetCurrentUserContext)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/tenants", wrapper.ListAccessibleTenants)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/session/switch-tenant", wrapper.SwitchTenant)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/session/step-up", wrapper.StepUpSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/session/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/organizations", wrapper.ListOrganizations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/organizations", wrapper.CreateTenantOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/organizations/{organizationId}", wrapper.GetOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/organizations/{organizationId}", wrapper.UpdateOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/people", wrapper.ListPeople)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/people", wrapper.CreatePerson)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/people/{personId}", wrapper.GetPerson)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/eligibility/checks", wrapper.CheckEligibility)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/service-requests", wrapper.ListServiceRequests)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/service-requests", wrapper.CreateServiceRequest)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/service-requests/{requestId}", wrapper.GetServiceRequest)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/service-requests/{requestId}", wrapper.UpdateDraftServiceRequest)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/service-requests/{requestId}/submit", wrapper.SubmitServiceRequest)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/service-requests/{requestId}/cancel", wrapper.CancelServiceRequest)
	})

	return r
}

